// Half of the WP21 S1 boundary case: package-scoped symbols stop at functions,
// so two packages declaring one class name are still one `%struct.Node`. The
// class is private to the package and never crosses a module boundary — the
// clash is the *name*, not anything either program did with it.

class Node {
  x: i32 = 1;
}

export const first = (): i32 => new Node().x;
